// sidebar-fx: animates herdr's Agents and Spaces panels by streaming
// display-only metadata tokens ($charge, $fx and session stats) over
// herdr's socket API. Colors come from `rules` in config.toml, generated by
// build-config.js from the same frame data in frames.js.
'use strict';

const fs = require('fs');
const net = require('net');
const path = require('path');
const os = require('os');

const SOCKET = process.env.HERDR_SOCKET_PATH
  || path.join(process.env.APPDATA || path.join(os.homedir(), '.config'), 'herdr', 'herdr.sock');
const PIPE = process.platform === 'win32' ? `\\\\.\\pipe\\${SOCKET}` : SOCKET;

const SOURCE = 'custom:sidebar-fx';
const FRAME_MS = 120;
const POLL_MS = 1000;
const TTL_MS = 1500;
const STATS_MS = 3000;
const STATS_TTL_MS = 10000;
const CLAUDE_PROJECTS = path.join(os.homedir(), '.claude', 'projects');

// Frame strings live in frames.js; the config generator builds color rules from the same data.
const { SPIN, GLITCH, SCAN_CAPS, SCAN_COLORS, ACCENT, activityBar } = require('./frames');
const activity = require('./activity');
const hermes = require('./hermes');
const spaces = require('./spaces');
const PULSE = ['◉', '○'];
const GLITCH_CHANCE = 0.04; // per tick, per pane
const glitchUntil = new Map(); // pane_id -> { until, text }
// Bar colors are saved so a restart doesn't repaint every bar at once.
const COLORS_FILE = path.join(process.env.APPDATA || path.join(os.homedir(), '.config'), 'herdr', 'bar-colors.json');
const NEW_RUN_MS = 15000; // a pane must rest this long before its next run gets a new color
const barColor = new Map(); // pane_id -> { color, working, restSince }
try {
  for (const [pane, color] of Object.entries(JSON.parse(fs.readFileSync(COLORS_FILE, 'utf8')))) {
    barColor.set(pane, { color, working: null, restSince: 0 });
  }
} catch { /* first run */ }

let seq = Date.now() * 100;
let tick = 0;
let agents = [];
let hermesInfo = new Map(); // pane_id -> live Hermes session info
let reqId = 0;

// herdr answers one request per connection, so each call opens its own.
function send(method, params, cb) {
  const id = `fx_${++reqId}`;
  const sock = net.connect(PIPE);
  let buf = '';
  sock.setEncoding('utf8');
  sock.setTimeout(2000, () => sock.destroy());
  sock.on('connect', () => sock.write(JSON.stringify({ id, method, params }) + '\n'));
  sock.on('data', (chunk) => {
    buf += chunk;
    const i = buf.indexOf('\n');
    if (i < 0) return;
    sock.end();
    if (!cb) return;
    try { cb(JSON.parse(buf.slice(0, i))); } catch { /* ignore malformed lines */ }
  });
  sock.on('error', () => { if (method === 'agent.list') agents = []; });
}

function claudeSession(a) {
  const ref = a && a.agent_session;
  return ref && ref.agent === 'claude' && ref.value ? readSession(ref.value) : null;
}

function poll() {
  send('agent.list', {}, (msg) => {
    agents = (msg.result && msg.result.agents) || [];
    hermesInfo = hermes.read(agents.filter((a) => a.agent === 'hermes'));
    for (const a of agents) claudeSession(a); // keep activity fresh
    if (msg.result) activity.track(agents, (a) => ({ ...statsTokens(a), status: effectiveStatus(a) }));
    log(`${agents.length} agent(s)`);
  });
}

// Occasionally corrupt the activity label for 1-3 ticks.
function label(paneId, t, text) {
  let g = paneId && glitchUntil.get(paneId);
  if (paneId && (!g || g.until < t) && Math.random() < GLITCH_CHANCE) {
    g = { until: t + 1 + Math.floor(Math.random() * 3), text: GLITCH[Math.floor(Math.random() * GLITCH.length)] };
    glitchUntil.set(paneId, g);
  }
  return g && g.until >= t ? g.text : `${SPIN[t % SPIN.length]} ${text}`;
}

// herdr can still say "working" after Claude has finished its turn, so trust
// the transcript's end_turn marker when there is one. For Hermes it can say
// "idle" while he or his subagents are busy, so trust his session store.
function effectiveStatus(a) {
  const h = hermesInfo.get(a.pane_id);
  if (h && h.busy && a.agent_status !== 'blocked') return 'working';
  const s = claudeSession(a);
  return a.agent_status === 'working' && s && s.turnDone ? 'idle' : a.agent_status;
}

// Frame strings are distinct per tick so config rules can color each one.
function paneTokens(status, t, a) {
  switch (status) {
    case 'working': {
      const h = a && hermesInfo.get(a.pane_id);
      if (h) return { fx: label(a.pane_id, t, h.activity.slice(0, 18)) };
      const s = claudeSession(a);
      const activity = (s && s.activity) || 'thinking';
      const text = activity === 'tool' ? `⚙ ${s.toolName || 'tool'}`.slice(0, 18) : activity;
      return { fx: label(a && a.pane_id, t, text) };
    }
    case 'blocked': return { fx: `${PULSE[Math.floor(t / 4) % 2]} needs you` };
    case 'done': return { fx: '✓ done' };
    default: return { fx: '◌ idle' };
  }
}

function saveColors() {
  const live = new Set(agents.map((a) => a.pane_id));
  const out = {};
  for (const [pane, c] of barColor) if (live.has(pane)) out[pane] = c.color;
  try { fs.writeFileSync(COLORS_FILE, JSON.stringify(out)); } catch { /* best effort */ }
}

// A color no other pane is showing, and not `avoid`, when there is one.
function freeColor(paneId, avoid) {
  const others = new Set(agents.map((a) => a.pane_id).filter((p) => p !== paneId));
  const taken = new Set([...barColor].filter(([p]) => others.has(p)).map(([, c]) => c.color));
  const all = [...SCAN_CAPS.keys()].filter((i) => i !== avoid);
  const free = all.filter((i) => !taken.has(i));
  const pool = free.length ? free : all;
  return pool[Math.floor(Math.random() * pool.length)];
}

// Each pane keeps its own color. It changes only when that pane starts a new
// run after a real rest, never because of another pane or a brief pause.
function scanColor(paneId, status) {
  const now = Date.now();
  const working = status === 'working';
  let c = barColor.get(paneId);
  if (!c) {
    c = { color: freeColor(paneId), working, restSince: now };
    barColor.set(paneId, c);
    saveColors();
  }
  if (c.working === null) c.working = working; // restored from disk: keep its color
  if (working && !c.working && now - c.restSince >= NEW_RUN_MS) {
    c.color = freeColor(paneId, c.color);
    saveColors();
  }
  if (!working && c.working) c.restSince = now;
  c.working = working;
  return c.color;
}

// Focused pane: herdr has a single accent color (focused border, highlights),
// so it follows the focused agent's bar color, and that pane's border label
// carries a slow marker while it works.
const CONFIG = path.join(process.env.APPDATA || path.join(os.homedir(), '.config'), 'herdr', 'config.toml');
const BORDER_MS = 300;
const BORDER_TRACK = 7;
const OUR_LABEL = /^[†✠]/;
let accent = null;  // accent config.toml has now
let labeled = null; // { pane, label } we last put on a border
let borderTick = 0;

function setAccent(color) {
  if (color === accent) return;
  accent = color;
  let text;
  try { text = fs.readFileSync(CONFIG, 'utf8'); } catch { return; }
  const next = text.replace(/^accent = "[^"]*"$/gm, `accent = "${color}"`);
  if (next === text) return;
  try { fs.writeFileSync(CONFIG, next); } catch { return; }
  send('server.reload_config', {}, report);
}

function borderLabel(a, status, t) {
  const name = a.agent || 'agent';
  if (status === 'blocked') return `✠ ${name} · needs you ✠`;
  if (status !== 'working') return null;
  const period = 2 * (BORDER_TRACK - 1);
  const p = t % period;
  const x = p < BORDER_TRACK ? p : period - p;
  const track = [...Array(BORDER_TRACK).keys()].map((i) => (i === x ? '◆' : '·')).join('');
  return `† ${name} ${track} †`;
}

// Subagent watch panes (subagent-view.js) name their own borders.
const isSubagentView = (a) => !a.agent_session && /^[⑂✓] /.test(a.terminal_title || '');

function border() {
  borderTick++;
  const a = agents.find((x) => x.focused);
  if (labeled && (!a || labeled.pane !== a.pane_id)) {
    send('pane.rename', { pane_id: labeled.pane, label: null }, report);
    labeled = null;
  }
  if (!a) return setAccent(ACCENT);
  const status = effectiveStatus(a);
  const color = scanColor(a.pane_id, status);
  setAccent(SCAN_COLORS[color]);
  if (isSubagentView(a)) return;
  const label = borderLabel(a, status, borderTick);
  if (labeled && labeled.label === label) return;
  if (!label && !labeled) return;
  send('pane.rename', { pane_id: a.pane_id, label }, report);
  labeled = label ? { pane: a.pane_id, label } : null;
}

// Clear border labels left behind if sidebar-fx was stopped mid-animation.
function clearOldLabels() {
  send('pane.list', {}, (msg) => {
    for (const p of (msg.result && msg.result.panes) || []) {
      if (p.label && OUR_LABEL.test(p.label)) send('pane.rename', { pane_id: p.pane_id, label: null }, report);
    }
  });
}

function rollup(states) {
  for (const s of ['blocked', 'working', 'done']) if (states.includes(s)) return s;
  return 'idle';
}

function frame() {
  tick++;
  const byWorkspace = new Map();
  for (const a of agents) {
    const status = effectiveStatus(a);
    const tokens = { ...paneTokens(status, tick, a), charge: activityBar(status, tick, scanColor(a.pane_id, status)) };
    send('pane.report_metadata', { pane_id: a.pane_id, source: SOURCE, tokens, seq: ++seq, ttl_ms: TTL_MS }, report);
    if (!byWorkspace.has(a.workspace_id)) byWorkspace.set(a.workspace_id, []);
    byWorkspace.get(a.workspace_id).push(status);
  }
  for (const [workspaceId, states] of byWorkspace) {
    const { fx } = paneTokens(rollup(states), tick);
    send('workspace.report_metadata', { workspace_id: workspaceId, source: SOURCE, tokens: { fx }, seq: ++seq, ttl_ms: TTL_MS }, report);
  }
}

// Session stats: incrementally tail Claude Code transcripts (~/.claude/projects/*/<session>.jsonl).
const sessions = new Map();

function findTranscript(sessionId) {
  try {
    for (const dir of fs.readdirSync(CLAUDE_PROJECTS)) {
      const file = path.join(CLAUDE_PROJECTS, dir, `${sessionId}.jsonl`);
      if (fs.existsSync(file)) return file;
    }
  } catch { /* no Claude projects dir */ }
  return null;
}

function readSession(sessionId) {
  let s = sessions.get(sessionId);
  if (!s) {
    s = { file: findTranscript(sessionId), offset: 0, rest: '', start: null, model: null, ctx: 0, turns: 0, tools: 0, out: new Map(), aiTitle: null };
    sessions.set(sessionId, s);
  }
  // Claude writes the transcript after the session is reported, so keep looking.
  if (!s.file) s.file = findTranscript(sessionId);
  if (!s.file) return s;
  let size;
  try { size = fs.statSync(s.file).size; } catch { return s; }
  if (size <= s.offset) return s;
  const fd = fs.openSync(s.file, 'r');
  const chunk = Buffer.alloc(size - s.offset);
  fs.readSync(fd, chunk, 0, chunk.length, s.offset);
  fs.closeSync(fd);
  s.offset = size;
  const lines = (s.rest + chunk.toString('utf8')).split('\n');
  s.rest = lines.pop();
  for (const line of lines) {
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    if (!s.start && e.timestamp) s.start = Date.parse(e.timestamp);
    if (e.type === 'ai-title' && e.aiTitle) s.aiTitle = e.aiTitle;
    if (e.type === 'user' && !e.isMeta && e.message) {
      const c = e.message.content;
      const isPrompt = typeof c === 'string' || (Array.isArray(c) && c.some((b) => b.type === 'text'));
      if (isPrompt) s.turns++;
      // A prompt or tool result means the model is generating again.
      s.activity = 'thinking';
      s.turnDone = false;
    }
    if (e.type === 'assistant' && e.message) {
      const m = e.message;
      if (m.model && !m.model.startsWith('<')) s.model = m.model;
      s.turnDone = m.stop_reason === 'end_turn';
      const u = m.usage;
      if (u) {
        s.ctx = (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0);
        s.out.set(m.id, u.output_tokens || 0);
      }
      if (Array.isArray(m.content)) {
        s.tools += m.content.filter((b) => b.type === 'tool_use').length;
        const last = m.content[m.content.length - 1];
        if (last && last.type === 'tool_use') { s.activity = 'tool'; s.toolName = last.name; }
        else if (last && last.type === 'thinking') s.activity = 'thinking';
        else if (last && last.type === 'text') s.activity = 'writing';
      }
    }
  }
  return s;
}

function compact(n) {
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e3) return `${Math.round(n / 1e3)}k`;
  return String(n);
}

function duration(ms) {
  const m = Math.floor(ms / 60000);
  return m >= 60 ? `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m` : `${m}m`;
}

// Hermes cards: same slots as Claude's, filled from his session store.
function hermesStats(a, { session: s, subs }) {
  const title = a.name || s.title || a.terminal_title_stripped || null;
  const cost = s.estimated_cost_usd > 0 ? ` $${s.estimated_cost_usd.toFixed(2)}` : '';
  return {
    title: title && title.slice(0, 80),
    model: s.model ? s.model + cost : null,
    ctx: `⇣ ${compact(s.input_tokens || 0)} in`,
    out: `↑ ${compact(s.output_tokens || 0)} out`,
    age: s.started_at ? `◷ ${duration(Date.now() - s.started_at * 1000)}` : null,
    turns: `↳ ${s.message_count || 0} msgs`,
    tools: `⚒ ${s.tool_call_count || 0} tools`,
    subs: subs.total ? `⑂ ${subs.live}/${subs.total} subs` : null,
  };
}

function statsTokens(a) {
  const h = hermesInfo.get(a.pane_id);
  if (h) return hermesStats(a, h);
  const s = claudeSession(a);
  const title = a.name || (s && s.aiTitle) || a.terminal_title_stripped || null;
  if (!s || !s.file) return { title, model: null, ctx: null, age: null, turns: null, tools: null, out: null };
  let out = 0;
  for (const v of s.out.values()) out += v;
  return {
    title: title && title.slice(0, 80),
    model: s.model ? s.model.replace(/^claude-/, '').replace(/-(\d+)-(\d+)$/, ' $1.$2') : null,
    ctx: s.ctx ? `◔ ${compact(s.ctx)} ctx` : null,
    age: s.start ? `◷ ${duration(Date.now() - s.start)}` : null,
    turns: `↳ ${s.turns} prompts`,
    tools: `⚒ ${s.tools} tools`,
    out: `↑ ${compact(out)} out`,
  };
}

function stats() {
  const byWorkspace = new Map();
  for (const a of agents) {
    send('pane.report_metadata', { pane_id: a.pane_id, source: SOURCE, tokens: statsTokens(a), seq: ++seq, ttl_ms: STATS_TTL_MS }, report);
    if (!byWorkspace.has(a.workspace_id)) byWorkspace.set(a.workspace_id, []);
    byWorkspace.get(a.workspace_id).push(effectiveStatus(a));
  }
  for (const [workspaceId, states] of byWorkspace) {
    send('workspace.report_metadata', { workspace_id: workspaceId, source: SOURCE, tokens: spaces.tokens(states), seq: ++seq, ttl_ms: STATS_TTL_MS }, report);
  }
}

function report(msg) {
  if (msg.error) log(`error: ${JSON.stringify(msg.error)}`);
}

function log(msg) {
  if (process.env.SIDEBAR_FX_DEBUG) console.log(`[sidebar-fx] ${msg}`);
}

activity.trim();
spaces.start();
poll();
setInterval(poll, POLL_MS);
setInterval(stats, STATS_MS);
setInterval(frame, FRAME_MS);
clearOldLabels();
setInterval(border, BORDER_MS);
